export const QUIZ_ITEMS = [
  { id: "1515", section: "الفرائض والمواريث", category: "المواريث", level: "متوسط", question: "ما موانع الإرث الثلاثة في الفقه الإسلامي؟", answer: "ثلاثة: 1- القتل العمد العدوان (القاتل لا يرث ممن قتله). 2- اختلاف الدين (المسلم لا يرث الكافر ولا الكافر المسلم بالإجماع). 3- الرق (العبد لا يرث ولا يُورَث في حكمه).", explanation: "يُستفاد منه في باب المواريث. يُستفاد منه في باب المواريث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1516", section: "الفرائض والمواريث", category: "الفروض", level: "صعب", question: "كم فريضة حددها القرآن الكريم في المواريث؟", answer: "ستة فروض مقدّرة: النصف (1/2)، الربع (1/4)، الثمن (1/8)، الثلثان (2/3)، الثلث (1/3)، السدس (1/6) — وكل منها لمستحق محدد بآيات النساء (11-12 و176).", explanation: "يُستفاد منه في باب الفروض. يُستفاد منه في باب الفروض مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1517", section: "الفرائض والمواريث", category: "الحجب", level: "صعب", question: "ما الفرق بين حجب الحرمان وحجب النقصان؟", answer: "حجب الحرمان: حجب الوارث كلياً عن الإرث — كحجب الأخ بالابن. حجب النقصان: نقل الوارث من فرض أعلى إلى أدنى — كانتقال الزوج من النصف (1/2) إلى الربع (1/4) عند وجود الولد.", explanation: "يُستفاد منه في باب الحجب. يُستفاد منه في باب الحجب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1518", section: "الفرائض والمواريث", category: "أصحاب الفروض", level: "متوسط", question: "من الورثة الذين لا يُحجبون حجب حرمان أبداً؟", answer: "ستة: الأب، الأم، الابن، البنت، الزوج، الزوجة — لا يُحجبون حجب حرمان مطلقاً وإن نقص نصيبهم بحجب النقصان (كانتقال الزوج من النصف إلى الربع عند وجود الولد). أما ابن الابن (الحفيد) فليس منهم؛ إذ يُحجب حجب حرمان تاماً بوجود الابن.", explanation: "يُستفاد منه في باب أصحاب الفروض. يُستفاد منه في باب أصحاب الفروض مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1519", section: "الفرائض والمواريث", category: "الوصية", level: "متوسط", question: "ما أقصى ما يجوز للمسلم إيصاء به من ماله؟", answer: "لا تجوز الوصية بأكثر من ثلث المال للأجانب — لحديث سعد رضي الله عنه: «الثلث والثلث كثير» (البخاري). ولا تجوز الوصية لوارث ألبتة إلا بإجازة بقية الورثة.", explanation: "يُستفاد منه في باب الوصية. يُستفاد منه في باب الوصية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1520", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من هم أصحاب الفروض المحددة في القرآن؟", answer: "أصحاب الفروض المقدَّرة في القرآن: 1) الزوج: النصف أو الربع. 2) الزوجة/الزوجات: الربع أو الثمن. 3) الأم: الثلث أو السدس. 4) الأب: السدس (عصبة). 5) البنت/البنات: النصف أو الثلثان. 6) الأخت الشقيقة: النصف أو الثلثان. 7) الجدة: السدس. 8) الأخ لأم والأخت لأم: السدس أو الثلث.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1521", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من الذين يُحجَبون حجب حرمان من الميراث؟ اذكر أمثلة.", answer: "حجب الحرمان: حرمان الوارث من الإرث بسبب وجود وارث أقوى منه. أمثلة: 1) الجد يُحجَب بوجود الأب. 2) الإخوة يُحجَبون بوجود الابن أو الأب. 3) بنت الابن تُحجَب بوجود بنتين فأكثر إلا إذا وُجد معها ابن ابن. 4) الأخت لأم تُحجَب بوجود الفرع الوارث أو الأصل الذكر. والمانعون من الإرث: الكفر، والقتل العمد، والرق.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1522", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما الفرق بين اسمَي الله «الغفور» و«الغفّار»؟", answer: "الغفور: يدل على سعة المغفرة في ذاتها مهما عظمت الذنوب. الغفّار: يدل على كثرة المغفرة وتكرارها مراراً وتكراراً، أي كثير المغفرة لا ينضب عفوه. والاسمان معاً يُعطيان المؤمن رجاءً بسعة المغفرة واستمرارها مهما كان العبد مذنباً وكثُرت عودته بالتوبة.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1523", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "سهل", question: "ما معنى اسم الله «الحليم» وكيف يُفرَّق بينه وبين الصبور؟", answer: "الحليم: الذي لا يستفزه عصيان العصاة ولا يُقلقه انتشار المعاصي، فيؤخر العقوبة رحمةً وحكمةً. الصبور في المقابل: يركز على التأخير الطويل مع الإحاطة بالخلق. الحليم يُشير إلى الطمأنينة التامة وعدم تغيّر حال الله بمعصية عبده.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1524", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما معنى اسمَي الله «الوكيل» و«الكفيل»؟", answer: "الوكيل: الذي يتولى مصالح عباده ويكفيهم ما يهمهم. قال تعالى: ﴿وَكَفَىٰ بِاللَّهِ وَكِيلاً﴾. ومعناه التفويض التام إليه والاعتماد عليه وحده في جلب المصالح ودرء المفاسد. وهو ضمنياً يتضمن الكفالة والرعاية الكاملة لمن توكل عليه.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1525", section: "الأسماء الحسنى", category: "الأسماء الحسنى عموماً", level: "سهل", question: "كم اسماً من أسماء الله الحسنى وردت في الحديث المشهور عند الترمذي وابن ماجه؟", answer: "تسعة وتسعون اسماً في حديث: «إن لله تسعة وتسعين اسماً مئةً إلا واحداً من أحصاها دخل الجنة» (البخاري ومسلم). غير أن العلماء اختلفوا في تعداد تلك الأسماء لأن الحديث في الصحيحين لم يذكرها، بل ذِكرها في رواية الترمذي من زيادة راوٍ يناقشها العلماء.", explanation: "يُستفاد منه في باب الأسماء الحسنى عموماً. يُستفاد منه في باب الأسماء الحسنى عموماً مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1526", section: "الفتوحات الإسلامية", category: "المعارك", level: "متوسط", question: "ما معركة اليرموك؟", answer: "فتح عظيم في الشام هزم فيه المسلمون الروم في رجب سنة 15هـ في خلافة عمر بن الخطاب رضي الله عنه؛ أميرُ الجيش أبو عبيدة بن الجرّاح، وتولّى قيادة القتال خالد بن الوليد، وبها زال حكم الروم عن الشام", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1527", section: "الفتوحات الإسلامية", category: "المعارك", level: "متوسط", question: "من قائد المسلمين في معركة القادسية؟", answer: "سعد بن أبي وقاص رضي الله عنه — كانت في شعبان سنة 15هـ في خلافة عمر بن الخطاب، وقائد الفرس فيها رستم وقُتل فيها، وكانت مفتاح فتح العراق", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1528", section: "الفتوحات الإسلامية", category: "المعارك", level: "صعب", question: "ما معركة حطين وما أهميتها؟", answer: "معركة فاصلة في ربيع الآخر سنة 583هـ قادها صلاح الدين الأيوبي وهزم فيها الصليبيين هزيمة حطّمت قوّتهم في الشام، فاستُردّ بعدها بيت المقدس في رجب من السنة نفسها بعد نحو إحدى وتسعين سنة هجرية (88 سنة ميلادية) من احتلاله (وقع في أيديهم سنة 492هـ)", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1529", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "سهل", question: "في أي عام فُتحت مكة المكرمة؟", answer: "في رمضان من السنة الثامنة للهجرة (8هـ/630م)، بعد أن نقضت قريش صلح الحديبية بإعانة حلفائها بني بكر على خزاعة حلفاء النبي ﷺ؛ ودخلها ﷺ من غير قتال عامّ إلا مناوشة يسيرة في ناحية خالد بن الوليد رضي الله عنه، وأمّن أهلها فقال: «اذهبوا فأنتم الطلقاء» (عند ابن هشام وأهل المغازي). وأكثر المفسرين على أن «الفتح» في قوله تعالى ﴿إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ﴾ [النصر: 1] هو فتح مكة", explanation: "يُستفاد منه في باب الفتوحات الإسلامية. يُستفاد منه في باب الفتوحات الإسلامية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1530", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من قاد فتح القسطنطينية وفي أي عام؟", answer: "السلطان محمد الثاني العثماني الملقَّب بـ«الفاتح» يوم الثلاثاء العشرين من جمادى الأولى سنة 857هـ / التاسع والعشرين من مايو 1453م، فصارت القسطنطينية (إسطنبول) عاصمةَ الدولة بعد بورصة ثم أدرنة. ويربط كثير من أهل العلم هذا الفتح بحديث: «لتُفتحنّ القسطنطينية، فلنعم الأمير أميرها ولنعم الجيش ذلك الجيش» (رواه أحمد في المسند 18189، والبخاري في «التاريخ الكبير»)، وقد تكلّم بعض المحدّثين في إسناده", explanation: "يُستفاد منه في باب الفتوحات الإسلامية. يُستفاد منه في باب الفتوحات الإسلامية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1531", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من فتح الشام في عهد أبي بكر الصديق ثم عمر بن الخطاب؟", answer: "بدأ الفتح بأمر أبي بكر الصدّيق رضي الله عنه، فوجّه إلى الشام أمراء منهم أبو عبيدة بن الجرّاح وعمرو بن العاص ويزيد بن أبي سفيان وشرحبيل بن حسنة رضي الله عنهم، وأمدّهم بخالد بن الوليد قادمًا من العراق. ثم كانت اليرموك في رجب سنة 15هـ في خلافة عمر بن الخطاب رضي الله عنه، وأميرُ الجيش يومئذ أبو عبيدة وقائدُ القتال خالد، وبها زال حكم الروم عن الشام، ثم فُتحت دمشق وبيت المقدس", explanation: "يُستفاد منه في باب الفتوحات الإسلامية. يُستفاد منه في باب الفتوحات الإسلامية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1532", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من فتح مصر وفي أي عهد؟", answer: "عمرو بن العاص رضي الله عنه في خلافة عمر بن الخطاب رضي الله عنه؛ ولم يكن الفتح في سنة واحدة: دخل مصر سنة 19هـ، وسقط حصن بابليون سنة 20هـ/641م، ثم فُتحت الإسكندرية سنة 21هـ. واختطّ الفسطاط فكانت أول مدينة أسّسها المسلمون بمصر، وبها مسجده أول مسجد بُني في مصر", explanation: "يُستفاد منه في باب الفتوحات الإسلامية. يُستفاد منه في باب الفتوحات الإسلامية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1533", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من قاد فتح الأندلس وفي أي عام؟", answer: "طارق بن زياد مولى موسى بن نصير والي إفريقية وبأمرٍ منه، عبر المضيق المعروف اليوم بمضيق جبل طارق سنة 92هـ/711م، وحُسم الأمر بهزيمة لُذريق ملك القوط في معركة وادي لكّة (شذونة)؛ ثم عبر موسى بن نصير في العام التالي بجيش آخر فأتمّا فتح ما بقي من المدن كإشبيلية وماردة", explanation: "يُستفاد منه في باب الفتوحات الإسلامية. يُستفاد منه في باب الفتوحات الإسلامية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1534", section: "الفتوحات الإسلامية", category: "الغزوات", level: "سهل", question: "كم كان عدد المسلمين في غزوة بدر الكبرى؟", answer: "ثلاث مئة وبضعة عشر رجلًا؛ وهو الثابت في صحيح البخاري عن البراء بن عازب رضي الله عنه قال: «كنّا نتحدّث أنّ أصحاب بدر ثلاث مئة وبضعة عشر». وأمّا عدد المشركين فتقديرُ أهل السير والمغازي (كابن إسحاق) بنحو تسع مئة إلى ألف، وهو تقديرٌ منهم لا نصٌّ مرفوع. وكانت في السابع عشر من رمضان سنة 2هـ، وسمّى الله يومَها «يوم الفرقان»", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1535", section: "الفتوحات الإسلامية", category: "الغزوات", level: "سهل", question: "متى كانت غزوة أُحد؟", answer: "في شوّال من السنة الثالثة للهجرة (3هـ)؛ خرج النبي ﷺ في نحو ألف فرجع عبد الله بن أُبَيّ بثلث الجيش، والمشركون نحو ثلاثة آلاف. وكانت الدائرة للمسلمين أوّلًا ثم انقلبت لمّا ترك الرماة مواقعهم، واستُشهد نحو سبعين من المسلمين منهم حمزة بن عبد المطلب رضي الله عنه؛ قال تعالى: ﴿حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ﴾ [آل عمران: 152]", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1536", section: "الفتوحات الإسلامية", category: "الغزوات", level: "متوسط", question: "لماذا سُميت غزوة الأحزاب بالخندق؟", answer: "لأن المسلمين حفروا خندقًا حول المدينة يمنع المشركين من اقتحامها — وأصل حفر الخندق ثابت في الصحيحين، وأمّا تعيين سلمان الفارسي رضي الله عنه مشيرًا به فمن رواية أهل السِّيَر. وسُمّيت «الأحزاب» لتحزّب قبائل المشركين واليهود على المسلمين، وكانت في شوّال سنة 5هـ في نحو عشرة آلاف من الأحزاب، ولم يقع بين الجيشين التحامٌ عامّ لأن الخندق حال بينهما", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1537", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من قاد الجيوش الإسلامية لفتح فارس وما أشهر معاركه؟", answer: "سعد بن أبي وقاص رضي الله عنه، وأشهر معاركه القادسية سنة 15هـ على المشهور عند أهل السير وقيل 14هـ، ثم فتح المدائن عاصمة الفرس — أمّا معركة نهاوند (21هـ) التي سمّاها المؤرخون «فتح الفتوح» فقادها النعمان بن مقرن المزني رضي الله عنه (واستُشهد فيها) لا سعد", explanation: "يُستفاد منه في باب الفتوحات الإسلامية. يُستفاد منه في باب الفتوحات الإسلامية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1538", section: "الفتوحات الإسلامية", category: "الغزوات", level: "صعب", question: "ما الحادثة التي نزل في مرجع النبي ﷺ منها قوله تعالى: ﴿إِنَّا فَتَحْنَا لَكَ فَتْحًۭا مُّبِينًۭا﴾؟", answer: "صلح الحديبية في ذي القعدة سنة 6هـ؛ ونزلت سورة الفتح وهو ﷺ راجعٌ منها بين مكة والمدينة لا في أثنائها، كما في حديث عمر بن الخطاب رضي الله عنه عند البخاري في كتاب المغازي (باب غزوة الحديبية). وهي معدودة عند أهل المغازي في مخارجه ﷺ ولم يقع فيها قتال، وسمّى الله الصلح فتحًا مبينًا لما أعقبه من الأمن ودخول الناس في الإسلام", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1539", section: "الفتوحات الإسلامية", category: "فتح مكة", level: "سهل", question: "في أي سنة فُتِحت مكة المكرمة؟", answer: "السنة الثامنة من الهجرة النبوية، في شهر رمضان — زمن فتح مكة المكرمة.", explanation: "يُستفاد منه في باب فتح مكة. يُستفاد منه في باب فتح مكة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1540", section: "الفتوحات الإسلامية", category: "الفتوحات الشامية", level: "متوسط", question: "ما معركة اليرموك وما نتيجتها؟", answer: "معركة فاصلة عام 15 هجرية بين المسلمين والروم في الشام، انتصر فيها المسلمون وأفضت إلى فتح بلاد الشام", explanation: "يُستفاد منه في باب الفتوحات الشامية. يُستفاد منه في باب الفتوحات الشامية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1541", section: "الفتوحات الإسلامية", category: "الفتوحات الفارسية", level: "متوسط", question: "ما معركة نهاوند وما لقبها؟", answer: "معركة نهاوند عام 21 هجرية، سُميت فتح الفتوح لأنها الضربة القاضية على الإمبراطورية الساسانية", explanation: "يُستفاد منه في باب الفتوحات الفارسية. يُستفاد منه في باب الفتوحات الفارسية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1542", section: "الفتوحات الإسلامية", category: "فتح مصر", level: "متوسط", question: "من قاد فتح مصر ومتى؟", answer: "عمرو بن العاص رضي الله عنه، عام 19-21 هجرية، وأسس الفسطاط عاصمةً للدولة الإسلامية في مصر", explanation: "يُستفاد منه في باب فتح مصر. يُستفاد منه في باب فتح مصر مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1543", section: "الفتوحات الإسلامية", category: "فتوح الشام", level: "متوسط", question: "ما معركة اليرموك وما أهميتها؟", answer: "معركة اليرموك (15هـ/ 636م): بين المسلمين بقيادة خالد بن الوليد وجيش الروم البيزنطي. انتصر فيها المسلمون نصراً ساحقاً فاتحاً لبلاد الشام كلها. تُعد من أكبر المعارك في التاريخ وأعظم فتوح الإسلام.", explanation: "يُستفاد منه في باب فتوح الشام. يُستفاد منه في باب فتوح الشام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1544", section: "الفتوحات الإسلامية", category: "فتوح العراق", level: "متوسط", question: "ما معركة القادسية ومن قائدها؟", answer: "معركة القادسية (14-15هـ/ 636م): بين المسلمين بقيادة سعد بن أبي وقاص والفرس الساسانيين. انتصر فيها المسلمون وفتحت العراق وأسقطت الإمبراطورية الساسانية. تُعد من أعظم الفتوح الإسلامية.", explanation: "يُستفاد منه في باب فتوح العراق. يُستفاد منه في باب فتوح العراق مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1545", section: "الفتوحات الإسلامية", category: "فتوح مصر", level: "متوسط", question: "من فاتح مصر للإسلام وما العام الذي فُتحت فيه؟", answer: "عمرو بن العاص رضي الله عنه فتحها عام 20هـ (641م). كانت تحت سيطرة الرومان البيزنطيين. وبنى عمرو مدينة الفسطاط أول مدينة إسلامية في مصر، وبنى مسجد عمرو أول مسجد في أفريقيا.", explanation: "يُستفاد منه في باب فتوح مصر. يُستفاد منه في باب فتوح مصر مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1546", section: "الفتوحات الإسلامية", category: "فتوح فارس", level: "متوسط", question: "ما المدائن وما أهميتها في الفتوحات الإسلامية؟", answer: "المدائن (Ctesiphon): عاصمة الفرس الساسانيين على نهر دجلة. فتحها سعد بن أبي وقاص عام 16هـ (637م). كانت من أعظم مدن العالم ومقر كسرى وملوك الفرس. فتحها أسقط الدولة الساسانية.", explanation: "يُستفاد منه في باب فتوح فارس. يُستفاد منه في باب فتوح فارس مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1547", section: "الفتوحات الإسلامية", category: "فتوح المغرب", level: "متوسط", question: "من قاد فتح شمال أفريقيا (إفريقية) وبنى مدينة القيروان لتكون قاعدة الفتح الإسلامي هناك؟", answer: "عقبة بن نافع رضي الله عنه — بنى مدينة القيروان عام 50هـ (670م) لتكون قاعدة الفتح الإسلامي في المغرب. وامتد الفتح حتى المحيط الأطلسي قبل دخول الأندلس.", explanation: "يُستفاد منه في باب فتوح المغرب. يُستفاد منه في باب فتوح المغرب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1548", section: "الفتوحات الإسلامية", category: "فتح مكة", level: "سهل", question: "في أي عام فُتحت مكة المكرمة؟ ومن أعلن أمان أهلها؟", answer: "فتحت مكة عام 8هـ (630م) في شهر رمضان. أعلن النبي ﷺ الأمان لأهل مكة قائلاً: «من دخل دار أبي سفيان فهو آمن، ومن أغلق بابه فهو آمن، ومن دخل المسجد فهو آمن» — وعفا عن أهلها جميعاً.", explanation: "يُستفاد منه في باب فتح مكة. يُستفاد منه في باب فتح مكة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1549", section: "الفتوحات الإسلامية", category: "فتح فلسطين", level: "متوسط", question: "من الخليفة الذي تسلّم مفاتح بيت المقدس في الفتح الإسلامي الأول؟", answer: "عمر بن الخطاب رضي الله عنه — جاء بنفسه من المدينة عام 16هـ (638م) لتسلّم مفاتح القدس من بطريرك المدينة صفرونيوس (سوفرونيوس). وكتب العهدة العمرية ضامناً أمان أهل إيلياء.", explanation: "يُستفاد منه في باب فتح فلسطين. يُستفاد منه في باب فتح فلسطين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1550", section: "الفتوحات الإسلامية", category: "المعارك", level: "متوسط", question: "ما معركة القادسية؟ ومتى وقعت؟ وما نتيجتها؟", answer: "معركة القادسية: إحدى أعظم المعارك في تاريخ الفتوحات الإسلامية. وقعت في خلافة عمر بن الخطاب رضي الله عنه؛ ذكرها الطبري وابن الأثير وابن كثير في حوادث سنة 14هـ، وذهب ابن إسحاق وغيره إلى أنها سنة 15هـ (636م). والقادسية موضعٌ بالعراق قريبٌ من الكوفة مما يلي البادية، وبقربه نهر العتيق. قادها سعد بن أبي وقاص رضي الله عنه من جانب المسلمين، وقاد الفرس رستم فرُّخزاد. ودارت أيامًا سمّاها أهل الأخبار: أرماث، وأغواث، وعِماس، وليلة الهرير، ثم كان الفتح في اليوم الرابع بانتصار ساحق للمسلمين ومقتل رستم. وكانت فاتحة لسقوط الإمبراطورية الساسانية الفارسية ودخول الإسلام بلاد فارس.", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1551", section: "الفتوحات الإسلامية", category: "المعارك", level: "متوسط", question: "ما معركة اليرموك؟ ومن قادَها؟ وما أهميتها؟", answer: "معركة اليرموك: وقعت في رجب سنة 15هـ (636م) على المشهور — وذكرها ابن كثير وابن الأثير في حوادث سنة 13هـ — بأرض حوران على نهر اليرموك بين الشام والأردن. وكان أميرَ الجيش أبو عبيدة بن الجراح رضي الله عنه، وفوَّض القيادة الميدانية يومئذٍ إلى خالد بن الوليد رضي الله عنه، في مواجهة الجيش البيزنطي بقيادة أحد قادة الإمبراطور هرقل. انتهت بهزيمة ساحقة للروم وفتح طريق الشام أمام الجيوش الإسلامية. وكانت نهاية الحكم البيزنطي في بلاد الشام وفلسطين. تُعدّ من أكبر المعارك في التاريخ العالمي.", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1552", section: "التجويد", category: "المخارج", level: "سهل", question: "ما مخارج الحروف الأساسية؟", answer: "خمسة مخارج عامة: الجوف (لحروف المد الثلاثة)، والحلق، واللسان، والشفتان، والخيشوم (مخرج الغنة). ويتفرع منها على المذهب المختار — وهو اختيار ابن الجزري — سبعة عشر مخرجًا خاصًّا", explanation: "يُستفاد منه في باب المخارج. يُستفاد منه في باب المخارج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1553", section: "التجويد", category: "المخارج", level: "متوسط", question: "من أي مخرج يخرج حرف الغين؟", answer: "من أدنى الحلق، أي أقربه إلى الفم، ومعه حرف الخاء. والحلق ثلاثة مخارج: أقصاه — وهو أبعده عن الفم — للهمزة والهاء، ووسطه للعين والحاء، وأدناه للغين والخاء", explanation: "يُستفاد منه في باب المخارج. يُستفاد منه في باب المخارج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1554", section: "التجويد", category: "الأحكام", level: "سهل", question: "ما الإدغام في التجويد؟", answer: "إدخال حرف ساكن في حرف متحرك بعده بحيث يصيران حرفاً واحداً مشدداً من جنس الثاني. وحروفه عند النون الساكنة والتنوين ستة مجموعة في «يرملون»، وينقسم إلى إدغام بغنة في حروف «ينمو»، وإدغام بغير غنة في اللام والراء", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1555", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما الإخفاء في التجويد؟", answer: "النطق بالنون الساكنة أو التنوين بصفة بين الإظهار والإدغام، عارياً عن التشديد، مع بقاء الغنة مقدار حركتين. وحروفه خمسة عشر، وهي الباقية بعد حروف الإظهار الستة وحروف الإدغام الستة وحرف الإقلاب (الباء)", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1556", section: "التجويد", category: "الأحكام", level: "صعب", question: "ما المد المتصل؟", answer: "مدٌّ سببه همزة وقعت بعد حرف المد في الكلمة نفسها، نحو ﴿ٱلسَّمَآءِ﴾ و﴿مَآءًۭ﴾، وحكمه الوجوب عند القراء ولذلك سُمي «المد الواجب»، ويُمدّ أربع أو خمس حركات في رواية حفص", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1557", section: "التجويد", category: "الأحكام", level: "صعب", question: "ما القلقلة في التجويد؟", answer: "اضطراب الصوت عند النطق بالحرف ساكناً حتى تُسمع له نبرة قوية، وحروفها خمسة مجموعة في «قُطْبُ جَدٍّ»: القاف والطاء والباء والجيم والدال. وتكون صغرى إذا سكن الحرف في وسط الكلمة، وكبرى إذا وقع الوقف عليه في آخرها", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1558", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما الغنة؟", answer: "صوت رنّان يخرج من الخيشوم لا عمل للسان فيه، وهي صفة لازمة للنون والميم في جميع أحوالهما؛ وتُكمَل مقدار حركتين في مواضعها: النون والميم المشدَّدتين، والإدغام بغنة، والإخفاء", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1559", section: "التجويد", category: "الأحكام", level: "سهل", question: "ما حكم قراءة القرآن بالتجويد؟", answer: "تعلُّمه وتعليمه فرض كفاية على الأمة. وأمّا تطبيقه فيُفرَّق فيه: ما يختلّ به المعنى أو تتغير به بنية الكلمة — وهو اللحن الجليّ كإبدال حرف بحرف أو تغيير حركة الإعراب — فلا يجوز باتفاق؛ وأمّا اللحن الخفيّ المتعلق بكمال الأداء كمقادير المدود وإتمام الغنّة فمحل خلاف بين أهل العلم: منهم من ألحقه بالواجب أخذًا بقول ابن الجزري «والأخذ بالتجويد حتمٌ لازم»، ومنهم من عدّه من كمال الأداء المستحبّ لا الواجب", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1560", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما أنواع المد في التجويد؟", answer: "قسمان: المد الطبيعي (الأصلي) وهو ما لا يقوم حرف المد إلا به ولا سبب بعده، ومقداره حركتان؛ والمد الفرعي وهو ما زاد على الطبيعي لسبب، والسبب إمّا همز (المتصل والمنفصل والبدل) وإمّا سكون (العارض للسكون واللازم بأنواعه)", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1561", section: "التجويد", category: "الأحكام", level: "صعب", question: "متى يكون الإدغام بغير غنة؟", answer: "إذا وقعت اللام أو الراء بعد نون ساكنة أو تنوين، فتُدغم فيهما بغير غنة، نحو ﴿مِّن لَّدُنْهُ﴾ و﴿مِّن رَّبِّهِمْ﴾. وأمّا حروف «ينمو» — الياء والنون والميم والواو — فالإدغام فيها بغنة", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1562", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما التفخيم والترقيق؟", answer: "التفخيم تسمين الحرف حتى يمتلئ الفم بصداه، والترقيق تنحيفه. فحروف الاستعلاء السبعة المجموعة في «خُصَّ ضَغْطٍ قِظْ» مفخَّمة دائماً، وسائر الحروف مرقَّقة، وتتردد بين الحالين الراء ولام لفظ الجلالة والألف تبعاً لما قبلها؛ فتُفخَّم الراء إذا كانت مفتوحة أو مضمومة أو ساكنة بعد فتح أو ضم، وتُرقَّق إذا كانت مكسورة أو ساكنة بعد كسر أصلي", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1563", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "سهل", question: "ما حكم النون الساكنة إذا جاء بعدها حرف من حروف الإخفاء؟", answer: "الإخفاء الحقيقي، وهو النطق بالنون الساكنة أو التنوين بصفةٍ بين الإظهار والإدغام، عاريًا عن التشديد، مع بقاء الغنة مقدار حركتين. وحروفه خمسة عشر، وهي الباقية بعد حروف الإظهار الستة وحروف الإدغام الستة وحرف الإقلاب (الباء)، ويقع في كلمة وفي كلمتين، نحو ﴿أَنفُسَهُمْ﴾ و﴿مِن قَبْلُ﴾", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1564", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "سهل", question: "ما حروف الإدغام بغنة للنون الساكنة والتنوين؟", answer: "أربعة مجموعة في «ينمو»: الياء والنون والميم والواو. وشرطه أن يكون الحرف في كلمة أخرى، فإن اجتمع مع النون في كلمة واحدة وجب «الإظهار المطلق»، ولم يقع ذلك في القرآن إلا في أربع كلمات: ﴿ٱلدُّنْيَا﴾ و﴿بُنْيَٰنٌۭ﴾ و﴿قِنْوَانٌۭ﴾ و﴿صِنْوَانٌۭ﴾. والإدغام في النون والميم كامل، وفي الياء والواو ناقص تبقى معه صفة الغنة دون ذات الحرف", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" }
];

